export type GlobalSearchType = typeof GlobalSearchType[keyof typeof GlobalSearchType];


export const GlobalSearchType = {
  case: 'case',
  client: 'client',
  property: 'property',
  lender: 'lender',
  task: 'task',
  message: 'message',
  notification: 'notification',
  event: 'event',
  user: 'user',
  document: 'document',
  invoice: 'invoice',
  renewal: 'renewal',
} as const;

export interface GlobalSearchHit {
  type: GlobalSearchType;
  id: number;
  /** Primary label of the record */
  title: string;
  /** Secondary context (client name */
  subtitle: string | null;
  /** Human label of the field the query matched */
  matchedField: string | null;
  /** Short excerpt of the matched field around the first hit */
  snippet: string | null;
  /** Status / stage / role chip */
  badge: string | null;
  /** In-app path that opens the record */
  href: string;
  /** Most relevant timestamp (updated */
  date: string | null;
}

export interface GlobalSearchGroup {
  type: GlobalSearchType;
  /** Total matches of this type */
  total: number;
  items: GlobalSearchHit[];
}

export interface GlobalSearchResults {
  query: string;
  /** Normalised search terms */
  terms: string[];
  total: number;
  /** Only types with at least one hit */
  groups: GlobalSearchGroup[];
}

